				select @@fields into #t 
				from v51 a 
					left join dmphi b on a.ma_phi = b.ma_phi 
					left join dmcong c on a.ma_cong = c.ma_cong 
					left join dmnt d on a.ma_nt = d.ma_nt
					left join dmdvt x on a.ma_dvt=x.dvt where @@key order by line
				select * from #t order by so_luong desc, line
				drop table #t









