dir$s51.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir, g = p.grid(0), dt = g.data;
  switch (id) {
    case 'ok':
		var d = p.valForm('ngay_hl'),d2 = p.valForm('ngay_hld');
		var k = $.date(d,"dd/mm/yy"),k2 = $.date(d2,"dd/mm/yy");
		if (p.valForm('ngay_hld') <= p.valForm('ngay_hl')) { 
			<!-- $.question('jkhj '+'Nhap sai ngay ??' ); -->
			<!-- $.showToast(p.msg('noDate')); -->

			$.alert(p.msg('noDate')+' ' + k + ' < ' + k2);			
			return false;
			Break;
			}	  		  
    default:
      break;
  }
  return true;
}
dir$s51.prototype.beforeButtonGridClick = function (id, gindex) {

  var p = this._dir;
  switch (id) {
    case '20':
        var p = document._dir;
	   if (p.valForm('ma_noi_di').trim() == '') {
        p.jObject('ma_noi_di').focus(); 
        return;
      }if (p.valForm('ma_noi_den').trim() == '') {
        p.jObject('ma_noi_den').focus(); 
        return;
      }
	  if (p.valForm('ds_cong').trim() == '') {
        p.jObject('ds_cong').focus(); 
        return;
      }  
      p.showFilter("s51BN1", null, {_ngay_ct: p.valForm('ngay_ct'),_ngay_ct1: p.valForm('ngay_hl'),_ngay_ct2: p.valForm('ngay_hld'),_unit_id: p.valForm('unit_id'),_ma_noi_di: p.valForm('ma_noi_di'),_ds_cong: p.valForm('ds_cong'), _ten_noi_di: p.valForm('ten_noi_di'), _ma_noi_den: p.valForm('ma_noi_den'), _ten_noi_den: p.valForm('ten_noi_den'),_cvc_yn: p.valForm('cvc_yn'),_xk_yn: p.valForm('xk_yn'),_nk_yn: p.valForm('nk_yn'),_pp_yn: p.valForm('pp_yn')});
	 return false;
      break;
    default:
      break;
  }
  return true;
}

dir$s51.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      dir$s51HiddenColumnByTran(p);
      break;
    case 'ma_ngv':
      dir$s51HiddenColumnByType(p);
      break;
    case 'ty_gia':
      p.calcExpressionAll(0, '!ty_gia');
      break;
    case 'ma_kh':
      p.request('Customer', '', ['ma_kh', 'ngay_ct', 'ma_nt']);
      break;
	case 'ma_dk_ngay':
      dir$s51HiddenColumnByDay(p);
	   break;
	case 'unit_id':
	 dir$s51DisabledMasterField(p, g);
      break;
	  case 'id_yc':
	 dir$s51DisabledMasterPort(p);
      break;
    default:
      break;
  }
}

function getRequest2(o){
	  var p = document._dir;
	   if (p.valForm('ma_noi_di').trim() == '') {
        p.jObject('ma_noi_di').focus(); 
        return;
      }if (p.valForm('ma_noi_den').trim() == '') {
        p.jObject('ma_noi_den').focus(); 
        return;
      }
	  if (p.valForm('ds_cong').trim() == '') {
		$.showToast(p.msg('EmptyContainer'));
        p.jObject('ds_cong').focus(); 
        return;
      }  
      p.showFilter("s51BN1", null, {_ngay_ct: p.valForm('ngay_ct'),_ngay_ct1: p.valForm('ngay_hl'),_ngay_ct2: p.valForm('ngay_hld'),_unit_id: p.valForm('unit_id'),_ma_noi_di: p.valForm('ma_noi_di'),_ds_cong: p.valForm('ds_cong'), _ten_noi_di: p.valForm('ten_noi_di'), _ma_noi_den: p.valForm('ma_noi_den'), _ten_noi_den: p.valForm('ten_noi_den'),_cvc_yn: p.valForm('cvc_yn'),_xk_yn: p.valForm('xk_yn'),_nk_yn: p.valForm('nk_yn'),_pp_yn: p.valForm('pp_yn')});

}
function getTax(o) {
  var p = document._dir;
  var tax = p.valForm('ma_so_thue').trim();
  var makh = p.valForm('ma_kh');
  if (tax.length != 10 && tax.length != 13) {
    $.showToast('Thông tin mã số thuế không đúng.');
    return;
  }

  $.invoke('GetTax', { taxCode: tax }, this, 30000
    , function (result) {
      if (result) {
        var obj = JSON.parse(result);
        p.valForm('ten_kh', obj.Name, true);
        p.valForm('dia_chi', obj.Address, true);
		p.valForm('ten_kh2', obj.Other, true);
		p.valForm('nguoi_lh', obj.Contact, true);
		p.valForm('dien_thoai', obj.Telephone, true);

      }
    }, function (event) {} );
}

