function dir$s51DisabledMasterField(p, g){
  var dt = g.data, rows = dt.findRow("[ma_phi].trim() != ''"), dis = rows.length > 0;
  p.setDisabled('unit_id', dis);
  p.setInactive('unit_id', true);
	if(p.options.action !="NEW") p.setDisabled(['ngay_ct', 'ma_nt','ty_gia','ma_gd','so_ct'], dis);

}
